  'legal.back': 'Back to home',
  'legal.contact': 'Contact: desporto24app@gmail.com',

  'privacy.title': 'Privacy Policy',
  'privacy.intro': 'This page explains in plain language which data Jynlo uses during the pilot, why it is used, and what rights you have.',
  'privacy.controller.title': 'Data controller',
  'privacy.controller.text': 'The Jynlo project manages the data processed on the platform. The controller\'s complete legal identification (name or entity, tax number and address) is pending confirmation before public or commercial launch.',
  'privacy.purposes.title': 'Data and purposes',
  'privacy.purposes.text': 'We use account and profile data for authentication, account management, discovery of people and activities, session participation, communication, security, support and operation of the pilot. Optional data should only be used when needed for the features you choose.',
  'privacy.location.title': 'Location',
  'privacy.location.text': 'When you allow device location, it is used to sort or find nearby activities. Device location should not be stored as a location history. Location attached to a session or venue may be stored as part of that content.',
  'privacy.retention.title': 'Retention',
  'privacy.retention.text': 'Retention periods for messages, attendance, contact requests and inactive accounts will be formally defined before public launch. During the pilot, data should be kept only for as long as necessary for service operation, security and validation.',
  'privacy.processors.title': 'Service providers and processors',
  'privacy.processors.text': 'The service may rely on infrastructure, email and authentication providers required to operate the platform. The final version of this policy will consolidate the applicable provider list and conditions.',
  'privacy.rights.title': 'Your rights',
  'privacy.rights.text': 'You may request access, correction, portability or deletion of your data and ask questions about processing through the contact shown on this page. Product controls for data export and account deletion are being implemented.',
  'privacy.security.title': 'Security',
  'privacy.security.text': 'Jynlo uses authentication, access controls and security mechanisms intended to protect accounts and data. No system eliminates all risk, so relevant incidents should be handled and communicated when applicable.',

  'terms.title': 'Terms of Use',
  'terms.intro': 'These provisional terms set out the basic rules for using Jynlo during the pilot.',
  'terms.scope.title': 'Pilot scope',
  'terms.scope.text': 'Jynlo helps people find places, activities and other sports participants. During the pilot, some features may change, become unavailable or be adjusted based on feedback and testing.',
  'terms.eligibility.title': 'Age and account',
  'terms.eligibility.text': 'You must be at least 18 years old to use the platform. You must provide valid account information, protect your credentials and not use another person\'s account.',
  'terms.conduct.title': 'Conduct',
  'terms.conduct.text': 'You must not harass, threaten, discriminate against or deceive other users, publish illegal or abusive content, send spam, attempt unauthorised access or use the platform for purposes incompatible with the sports community.',
  'terms.sessions.title': 'Sessions and reliability',
  'terms.sessions.text': 'When creating or joining a session, you should provide accurate information and act in good faith. Attendance, absences and cancellations may contribute to reliability indicators. Applicable rules and thresholds should be shown before they create consequences for a user.',
  'terms.moderation.title': 'Moderation and safety',
  'terms.moderation.text': 'Content or behaviour that breaches these rules may be reviewed, hidden or removed, and accounts may be limited when necessary to protect users and the platform. Where applicable, users should have an opportunity to challenge or request review.',
  'terms.account.title': 'Account and data',
  'terms.account.text': 'You can update your profile information and exercise the rights described in the Privacy Policy. Data export and account deletion controls are being implemented.',
  'terms.changes.title': 'Changes and contact',
  'terms.changes.text': 'These terms may be updated during the pilot. Material changes should be communicated clearly. For questions, use the contact shown on this page.',

